// A stand-in for the lab's clinic, for tests and for measuring the study. It enforces
// the rules SPEC.md states (one observer, arrival order, each once, the manager's limit)
// and hides a true mean difference. Not the lab's clinic: its arrivals, queue and
// difference distributions are our guesses, and the shapes are chosen to be unkind.
//
// makeClinic({ seed, mean, sd, shape, rate, minutes, servers, service, limit })
//   shape: 'normal' | 'skew' (exponential, right tail) | 'lumpy' (mostly mean−a, sometimes a big jump)
//          | 'heavy' (t, 3 df, scaled to sd) | 'zero' (no spread at all)
//   waits: 'queue' (from the servers) | 'tri' (triangular 14, 34, 54: the proposal's sizing)

function rng(seed) {
  let a = 0x9e3779b9 ^ (seed * 2654435761), b = 0x243f6a88 ^ seed, c = 0xb7e15162, d = seed | 0;
  const f = () => {
    a >>>= 0; b >>>= 0; c >>>= 0; d >>>= 0;
    const t = (a + b) | 0; a = b ^ (b >>> 9); b = (c + (c << 3)) | 0; c = (c << 21) | (c >>> 11);
    d = (d + 1) | 0; const r = (t + d) | 0; c = (c + r) | 0; return (r >>> 0) / 4294967296;
  };
  for (let i = 0; i < 12; i++) f();
  return f;
}

export function makeClinic({ seed = 1, mean = 0, sd = 5, shape = 'normal', rate = 1 / 12, minutes = 240,
  servers = 1, service = 10, waits = 'queue', limit = 5, slope = 0 } = {}) {
  const r = rng(seed);
  const exp = (m) => -Math.log(1 - r()) * m;
  const normal = () => Math.sqrt(-2 * Math.log(1 - r())) * Math.cos(2 * Math.PI * r());
  const tri = (a, m, b) => { const u = r(), f = (m - a) / (b - a); return u < f ? a + Math.sqrt(u * (b - a) * (m - a)) : b - Math.sqrt((1 - u) * (b - a) * (b - m)); };
  const diff = () => {
    switch (shape) {
      case 'normal': return mean + sd * normal();
      case 'heavy': { let c = 0; for (let i = 0; i < 3; i++) c += normal() ** 2; return mean + sd * normal() / Math.sqrt(c / 3) / Math.sqrt(3); }
      case 'skew': return mean + sd * (exp(1) - 1);
      case 'lumpy': { const p = 0.15, jump = sd / Math.sqrt(p * (1 - p)); return mean - p * jump + (r() < p ? jump : 0); }
      case 'zero': return mean;
      default: throw new Error(`unknown shape ${shape}`);
    }
  };
  const days = new Map(); // k -> { patients, truth: Map id -> {stop, tablet} }
  for (let k = 1; k <= limit; k++) {
    const patients = [];
    const truth = new Map();
    const free = Array(servers).fill(0);
    let t = exp(1 / rate);
    while (t < minutes) {
      const id = `m${k}p${patients.length + 1}`;
      free.sort((x, y) => x - y);
      const start = Math.max(t, free[0]);
      free[0] = start + exp(service);
      const stop = waits === 'tri' ? tri(14, 34, 54) : start - t;
      // `slope` breaks SPEC's promise on purpose (difference grows with wait); only for
      // measuring the diagnostic. 0 by default.
      const tablet = stop + diff() + slope * (stop - 20);
      patients.push({ id, arrive: t });
      truth.set(id, { stop, tablet });
      t += exp(1 / rate);
    }
    days.set(k, { patients, truth });
  }
  const trueMean = mean;
  let asked = 0, current = null, lastSeen = -Infinity, lastIdx = -1;
  const timedIds = new Set();
  const clinic = {
    morning(k) {
      if (k !== asked + 1) throw new Error(`morning ${k} asked out of order (next is ${asked + 1})`);
      if (k > limit) throw new Error(`the manager stops you at ${limit} mornings`);
      asked = k; current = days.get(k); lastSeen = -Infinity; lastIdx = -1;
      return current.patients.map((p) => ({ ...p }));
    },
    time(id) {
      if (!current) throw new Error('no morning asked for');
      const i = current.patients.findIndex((p) => p.id === id);
      if (i < 0) throw new Error(`${id} is not a patient of morning ${asked}`);
      if (timedIds.has(id)) throw new Error(`${id} timed twice`);
      if (i <= lastIdx) throw new Error(`${id} timed out of arrival order`);
      const p = current.patients[i];
      if (p.arrive < lastSeen) throw new Error(`${id} arrives at ${p.arrive} while the observer is busy until ${lastSeen}`);
      const { stop } = current.truth.get(id);
      timedIds.add(id); lastIdx = i; lastSeen = p.arrive + stop;
      return stop;
    },
    tablet(id) {
      for (let k = 1; k <= asked; k++) { const v = days.get(k).truth.get(id); if (v) return v.tablet; }
      throw new Error(`${id} is not a patient of a morning asked for`);
    },
  };
  Object.defineProperty(clinic, 'secret', { value: { trueMean, days }, enumerable: false });
  return clinic;
}

projects/p-stopwatch/fresh.mjs:
// fresh — evidence that knows what it was evidence of. Each evidence entry is stamped
// with the SHA-256 of every artifact that implements a requirement its check verifies;
// when any of those files changes, the entry stops counting.
import { createHash } from 'node:crypto';

const sha = (x) => createHash('sha256').update(typeof x === 'string' ? x : Buffer.from(x)).digest('hex');

// The artifacts an entry's check depends on: check -verifies-> req <-implements- artifact.
export function dependsOn(check, links) {
  const reqs = new Set(links.filter((l) => l.kind === 'verifies' && l.from === check).map((l) => l.to));
  return [...new Set(links.filter((l) => l.kind === 'implements' && reqs.has(l.to)).map((l) => l.from))].sort();
}

export function stamp(entry, links, readFile) {
  const digests = {};
  for (const path of dependsOn(entry.check, links)) digests[path] = sha(readFile(path));
  return { ...entry, digests };
}

// DECISION: an entry with no `digests` was never stamped, so nothing vouches for it: it is
// dropped. An entry stamped with an empty set (its check's requirements have no
// implementing artifact) has nothing that can go stale, so it stays. A file that can't be
// read no longer matches.
export function filter(evidence, links, readFile) {
  const cache = new Map();
  const now = (p) => {
    if (!cache.has(p)) { let d = null; try { d = sha(readFile(p)); } catch { d = null; } cache.set(p, d); }
    return cache.get(p);
  };
  return evidence.filter((e) => e && e.digests && typeof e.digests === 'object'
    && Object.entries(e.digests).every(([p, d]) => now(p) === d));
}

projects/p-stopwatch/harness.mjs:
// harness — one model, two runs: record it under runRealtime with a fake clock, replay
// its log under run(), and check every decision matches. No dependencies beyond des.
// Decisions SPEC.md leaves open are marked DECISION and listed in README.md.
import { Sim } from './tools/des/des.mjs';

// A clock that only moves when slept. sleep(ms) delivers at most one due injection:
// it advances the clock to that injection's time, injects, and returns, so the run
// loop sees the injected entry before anything later happens.
function fakeClock(sim, pending, scale, log) {
  const clock = {
    t: 0,
    now() { return clock.t; },
    sleep(ms) {
      const end = clock.t + ms;
      // DECISION: an injection is due when its clock time is strictly before the end of
      // the sleep. One at exactly the next event's time waits for the next sleep, so it
      // is delivered after every entry at that sim time, the same rule replay uses.
      if (pending.length && pending[0].at * scale < end) {
        const inj = pending.shift();
        clock.t = Math.max(clock.t, inj.at * scale);
        deliver(sim, inj.name, inj.value, log, inj.at);
      } else clock.t = end;
      return Promise.resolve();
    },
  };
  return clock;
}

// Inject and log the injection at the sim time it is actually delivered (from inside
// the scheduled entry), so the log's order is the order the model saw.
// DECISION (Morphyx, turn 2): the entry is scheduled at sim time `at` exactly, not at
// clock ÷ scale, which drifts an ulp (3 × 0.37 ÷ 0.37 = 2.9999999999999996). Same wake as
// des's _external; never earlier than now.
function deliver(sim, name, value, log, at) {
  const ext = sim._external;
  sim._external = function (fn) {
    sim._external = ext;
    sim.schedule(Math.max(0, at - sim.now), () => { log.push({ t: sim.now, kind: 'inject', data: { name, value: copy(value) } }); fn(); });
    if (sim._wake) { const w = sim._wake; sim._wake = null; w(); }
  };
  try { sim.inject(name, value); } finally { sim._external = ext; }
}

// DECISION: decision data is copied when written (JSON round trip), so a model that
// later mutates the object it logged can't rewrite history. Data must be JSON-able.
function copy(x) { return x === undefined ? null : JSON.parse(JSON.stringify(x)); }

function attach(sim, log) {
  sim.decide = (kind, data) => {
    if (typeof kind !== 'string' || !kind) throw new TypeError('decide needs a kind (string)');
    log.push({ t: sim.now, kind, data: copy(data) });
  };
}

export async function record(model, { seed, until, scale = 1, injections = [] } = {}) {
  if (typeof model !== 'function') throw new TypeError('record needs a model function');
  if (!(scale > 0)) throw new RangeError('scale must be > 0');
  for (const j of injections) if (!(j && j.at >= 0 && typeof j.name === 'string')) throw new RangeError(`bad injection ${JSON.stringify(j)}`);
  const log = [];
  // Stable sort: injections at the same time keep the order given.
  const pending = injections.map((j, i) => ({ ...j, i })).sort((a, b) => a.at - b.at || a.i - b.i);
  const sim = new Sim({ seed, clock: null });
  sim._clock = fakeClock(sim, pending, scale, log);
  attach(sim, log);
  await model(sim);
  await sim.runRealtime({ until, scale });
  return log;
}

export async function replay(model, log, { seed, until } = {}) {
  if (typeof model !== 'function') throw new TypeError('replay needs a model function');
  if (!Array.isArray(log)) throw new TypeError('replay needs a log array');
  const got = [];
  const sim = new Sim({ seed });
  attach(sim, got);
  await model(sim);
  for (const e of log) {
    if (e.kind !== 'inject') continue;
    // Recorded rule: an injection at t is delivered after every entry at times <= t
    // that existed when the clock passed t. run({until: t}) processes exactly those
    // (plus same-time entries they spawn, which in record also ran before the sleep).
    sim.run({ until: Math.max(e.t, sim.now) });
    // run() leaves now at until, so the injection lands at e.t, as in record.
    sim.inject(e.data.name, e.data.value);
  }
  if (until !== undefined) { if (until >= sim.now) sim.run({ until }); }
  else sim.run();
  const want = log.filter((e) => e.kind !== 'inject');
  const mismatches = [];
  const n = Math.max(want.length, got.length);
  for (let i = 0; i < n; i++) {
    const a = want[i], b = got[i];
    if (!same(a, b)) mismatches.push({ index: i, expected: a ?? null, got: b ?? null });
  }
  return { ok: mismatches.length === 0, mismatches };
}

function canon(x) {
  if (Array.isArray(x)) return '[' + x.map(canon).join(',') + ']';
  if (x && typeof x === 'object') return '{' + Object.keys(x).sort().map((k) => JSON.stringify(k) + ':' + canon(x[k])).join(',') + '}';
  return JSON.stringify(x);
}
function same(a, b) {
  if (!a || !b) return false;
  return Object.is(a.t, b.t) && a.kind === b.kind && canon(a.data) === canon(b.data);
}

