// Sizing for Bath (Modulo's proposal). Every plant number here is ASSUMED, not measured;
// the first job beyond the lab is a step test that replaces them.
// node modulo-bath.mjs            -> control-law table (simulated, instant)
// node modulo-bath.mjs --clock    -> runRealtime lateness on this machine (~20 s wall)
import { Sim } from '../tools/des/des.mjs';

// 5 L water, 1 kW element, 8 W/K loss, 20 s heater-to-sensor delay, DS18B20-like sensor.
const P = { C: 5 * 4186, UA: 8, W: 1000, amb: 20, dead: 20, noise: 0.05, q: 0.0625 };

export function bath({ law, tick = 1.5, seed = 1, hours = 4, set = 60, dropAt = null, dropFor = 0, faultAt = null, faultValue = null, plaus = false }) {
  const sim = new Sim({ seed });
  let T = P.amb, heat = 0, switches = 0, peak = -Infinity, offAt = null, tripped = null, tripAt = null;
  const pipe = new Array(P.dead).fill(0);           // transport delay, 1 s slots
  const temps = [];
  const gauss = () => { let u = 0; for (let i = 0; i < 12; i++) u += sim.random(); return u - 6; };
  sim.process(function* plant() {                   // plant + sensor, 1 s steps
    for (;;) {
      pipe.push(heat * P.W); const q = pipe.shift();
      T += (q - P.UA * (T - P.amb)) / P.C;
      peak = Math.max(peak, T); temps.push([sim.now, T]);
      const t = sim.now;
      const dropped = dropAt != null && t >= dropAt && t < dropAt + dropFor;
      const read = Math.round((T + P.noise * gauss()) / P.q) * P.q;   // fault: fresh, on time, wrong
      if (!dropped) sim.inject('temp', faultAt != null && t >= faultAt ? faultValue : read);
      yield sim.timeout(1);
    }
  });
  const setHeat = (h) => {
    if (h === heat) return;
    switches++; heat = h;
    if (!h && offAt == null && dropAt != null && sim.now >= dropAt) offAt = sim.now;
  };
  sim.process(function* ctl() {
    let lastSeen = 0, integ = 0, duty = 0, wStart = -Infinity, y = P.amb;
    const hist = [];
    for (;;) {
      // Not timeout(1): signals aren't buffered (des decision 8), and a 1 s tick racing a
      // 1 s sensor loses every reading that lands while the controller is between yields.
      const r = yield sim.anyOf([sim.timeout(tick), sim.signal('temp')]);
      if (r.index === 1) { y = r.value; lastSeen = sim.now; hist.push([sim.now, y, heat]); }
      if (plaus && !tripped) {                       // fresh but implausible -> latch
        const old = hist.filter(([t]) => t >= sim.now - 180 && t <= sim.now - 20);
        const onFrac = old.length ? old.filter(([, , h]) => h).length / old.length : 0;
        if (!Number.isFinite(y) || y < -10 || y > 105) tripped = 'range';
        else if (old.length >= 150) {
          // Energy balance with the (fitted) plant: what should 160 s of this heating have done?
          const span = old[old.length - 1][0] - old[0][0] + 1;
          const expect = (P.W * onFrac - P.UA * (old[0][1] - P.amb)) * span / P.C;
          if (expect >= 1.5 && y - old[0][1] < expect / 3) tripped = 'no-rise';
        }
        if (hist.length > 400) hist.splice(0, 200);
      }
      if (tripped && tripAt == null) tripAt = sim.now;
      if (tripped || sim.now - lastSeen > 5 || y > set + 5) { setHeat(0); continue; }   // fail-safe
      if (law === 'bang') { if (y < set - 0.3) setHeat(1); else if (y > set + 0.3) setHeat(0); }
      else {                                         // PI over a 10 s time-proportioning window
        if (sim.now - wStart >= 10) {
          wStart = sim.now; const e = set - y, Kp = 0.25, Ti = 600;
          const u0 = Kp * e + integ;
          if ((u0 < 1 || e < 0) && (u0 > 0 || e > 0)) integ += Kp * e * 10 / Ti;   // conditional integration
          duty = Math.min(1, Math.max(0, Kp * e + integ));
        }
        setHeat(sim.now - wStart < duty * 10 ? 1 : 0);
      }
    }
  });
  sim.run({ until: hours * 3600 });
  const reach = temps.findIndex(([, x]) => x >= set - 0.5);
  if (reach < 0) return { reached: false, max: Math.max(...temps.map(([, x]) => x)) };
  const after = temps.filter(([t]) => t >= temps[reach][0] + 1800).map(([, x]) => x).sort((a, b) => a - b);
  const pct = (p) => after[Math.floor(p * (after.length - 1))];
  if (faultAt != null) {
    const b = temps.find(([t, x]) => t >= faultAt && x >= 100);
    return { peak, boilMin: b ? (b[0] - faultAt) / 60 : null, tripped, tripAt };
  }
  return { reachMin: temps[reach][0] / 60, overshoot: peak - set, p1: pct(0.01) - set, p99: pct(0.99) - set,
           swPerHr: switches / hours, offAt, tripped, tripAt };
}

if (process.argv.includes('--clock')) {
  const sim = new Sim(); const lat = []; let t0;
  sim.process(function* () {
    for (let i = 0; i < 2000; i++) { yield sim.timeout(10); lat.push(performance.now() - t0 - sim.now); }
  });
  t0 = performance.now();          // taken before the call, so lateness is if anything overstated
  await sim.runRealtime({ scale: 1 });
  lat.sort((a, b) => a - b);
  const q = (p) => lat[Math.floor(p * (lat.length - 1))].toFixed(2);
  console.log(`runRealtime, 2000 ticks of 10 ms: lateness ms min ${q(0)} p50 ${q(.5)} p99 ${q(.99)} max ${q(1)}`);
} else if (process.argv[1] && import.meta.url.endsWith(process.argv[1].split('/').pop())) {
  console.log('law   seed reach(min) overshoot(K)  band p1..p99 (K)  switches/h');
  for (const law of ['bang', 'pi']) for (const seed of [1, 2, 3]) {
    const r = bath({ law, seed });
    console.log(`${law.padEnd(5)} ${seed}    ${r.reachMin.toFixed(1).padStart(5)}      ${r.overshoot.toFixed(2).padStart(5)}      ${r.p1.toFixed(2)}..${r.p99.toFixed(2)}       ${r.swPerHr.toFixed(0)}`);
  }
  for (const law of ['bang', 'pi']) {
    const r = bath({ law, dropAt: 3 * 3600, dropFor: 600 });
    console.log(`${law}: sensor silent from 10800 s -> heater off at ${r.offAt} s`);
  }
  // Council 2, round 2: the sensor keeps answering on time with a value that isn't the water.
  // The plant has no boiling, so peaks above 100 C mean "boiling dry", not a real temperature.
  for (const plaus of [false, true]) {
    console.log(plaus ? 'with plausibility (finite, -10..105 C, 160 s of heat must give >=1/3 of the rise the plant model expects, when it expects >=1.5 K):' : 'stale + over-temperature only:');
    for (const [name, v] of [['-127 (read fail)', -127], ['85.0 (power-on)', 85], ['NaN', NaN], ['frozen at 59.0', 59]])
      for (const law of ['bang', 'pi']) {
        const r = bath({ law, faultAt: 3 * 3600, faultValue: v, plaus });
        console.log(`  fault ${name.padEnd(17)} ${law.padEnd(4)} peak ${r.peak.toFixed(1)} C, 100 C ${r.boilMin == null ? 'never' : r.boilMin.toFixed(1) + ' min after fault'}` +
          (r.tripped ? `, tripped ${r.tripped} at +${r.tripAt - 10800} s` : ''));
      }
  }
  let falseTrips = 0, runs = 0;
  for (const law of ['bang', 'pi']) for (let seed = 1; seed <= 20; seed++) {
    runs++; if (bath({ law, seed, plaus: true }).tripped) falseTrips++;
    runs++; if (bath({ law, seed, plaus: true, dropAt: 3 * 3600, dropFor: 30 }).tripped) falseTrips++;
  }
  console.log(`plausibility false trips on healthy runs (incl. cold start, 30 s dropout): ${falseTrips}/${runs}`);
  const r1 = bath({ law: 'bang', tick: 1 });
  console.log(`bang with tick 1 s (same period as the sensor): ${JSON.stringify(r1)}`);
}

council/proposals/modulo-fit.mjs:
// Modulo, council 2 round 1. Can a first-order-plus-dead-time fit recover C, UA and dead time
// within 5% from a heating log, and how long/what shape must the log be?
// Plant = Modulo's assumed bath (proposals/modulo-bath.mjs). Prints the peak temperature each test input reaches.
// node proposals/modulo-fit.mjs
const P = { C: 5 * 4186, UA: 8, W: 1000, amb: 20, dead: 20, noise: 0.05, q: 0.0625 };
function rng(s) { return () => { s = (s * 1664525 + 1013904223) >>> 0; return s / 2 ** 32; }; }
function plant(u, seed) {
  const r = rng(seed); const g = () => { let x = 0; for (let i = 0; i < 12; i++) x += r(); return x - 6; };
  const pipe = new Array(P.dead).fill(0); let T = P.amb; const y = []; let Tmax = T;
  for (let t = 0; t < u.length; t++) {
    pipe.push(u[t] * P.W); T += (pipe.shift() - P.UA * (T - P.amb)) / P.C; Tmax = Math.max(Tmax, T);
    y.push(Math.round((T + P.noise * g()) / P.q) * P.q);
  }
  return { y, Tmax };
}
function shape(u, tau, L) {
  const a = Math.exp(-1 / tau); let x = 0; const s = [];
  for (let t = 0; t < u.length; t++) { const ui = t - L >= 0 ? u[t - L] : 0; x = a * x + (1 - a) * ui; s.push(x); }
  return s;
}
function fit(u, y, amb) {
  let best = null;
  const tryp = (tau, L) => {
    const s = shape(u, tau, L); let sxy = 0, sxx = 0;
    for (let i = 0; i < y.length; i++) { sxy += s[i] * (y[i] - amb); sxx += s[i] * s[i]; }
    const K = sxy / sxx; let e = 0;
    for (let i = 0; i < y.length; i++) { const d = y[i] - amb - K * s[i]; e += d * d; }
    return { tau, L, K, e };
  };
  for (let L = 0; L <= 60; L++) {
    let lo = 300, hi = 20000;
    for (let k = 0; k < 50; k++) { const m1 = lo + (hi - lo) / 3, m2 = hi - (hi - lo) / 3; if (tryp(m1, L).e < tryp(m2, L).e) hi = m2; else lo = m1; }
    const r = tryp((lo + hi) / 2, L); if (!best || r.e < best.e) best = r;
  }
  const UA = P.W / best.K; return { UA, C: best.tau * UA, L: best.L };
}
const cases = [
  ['full on, 1 h', 3600, () => 1],
  ['duty 0.3, 1 h', 3600, () => 0.3],
  ['duty 0.3, 2 h', 7200, () => 0.3],
  ['duty 0.3, 3 h', 10800, () => 0.3],
  ['full 28 min then off, 1 h', 3600, (t) => (t < 1680 ? 1 : 0)],
  ['full 28 min then off, 2 h', 7200, (t) => (t < 1680 ? 1 : 0)],
];
for (const ambErr of [0, 0.5]) {
  console.log(`\nambient ${ambErr ? '+0.5 K wrong' : 'known'} (seeds 1-10, worst case)`);
  for (const [name, N, f] of cases) {
    const u = Array.from({ length: N }, (_, t) => f(t));
    const w = { C: 0, UA: 0, L: 0 }; let Tm = 0;
    for (let seed = 1; seed <= 10; seed++) {
      const { y, Tmax } = plant(u, seed); Tm = Math.max(Tm, Tmax); const r = fit(u, y, P.amb + ambErr);
      w.C = Math.max(w.C, Math.abs(r.C / P.C - 1)); w.UA = Math.max(w.UA, Math.abs(r.UA / P.UA - 1)); w.L = Math.max(w.L, Math.abs(r.L - P.dead));
    }
    console.log(`${name.padEnd(28)} peak ${Tm.toFixed(1)} C | C ${(100 * w.C).toFixed(1)}%  UA ${(100 * w.UA).toFixed(1)}%  dead ±${w.L} s`);
  }
}

council/proposals/morphyx-keyholder.mjs:
// Keyholder sizing sketch (Morphyx, council 2). node proposals/morphyx-keyholder.mjs [seeds=200] [firstSeed=1]
// Question: once a second writer reaches the heater (an operator "boost" button), does the
// stale-sensor fail-safe still hold? Compares two arrangements of the SAME three writers:
//   lww  - last writer wins: each writer calls setHeat() directly (the usual first draft)
//   keys - every writer asks one arbiter; a safety demand outranks everyone, and only an
//          operator reset with a fresh reading lifts it. Every grant and refusal is logged.
// Plant numbers are Modulo's assumed bath (5 L, 1 kW, 8 W/K, 20 C ambient, set 60 C).
// The boost rate (1/h, 120 s) and the fault window are assumed too.
import { Sim } from '../tools/des/des.mjs';

const C = 5 * 4186, P = 1000, UA = 8, AMB = 20, SET = 60, H = 0.3, STALE = 5;
const CEIL = 2;                         // keys: boost is permitted only while the reading is <= set + 2 K
// First draft's bug (kept as a note, not a flag): the latch set a flag but nothing re-decided until
// someone else asked, so a boost already running kept heating a dead bath (3-4% of trials, up to 120 s).
// Two fixes are in: re-decide when latching, and re-decide every tick. Either alone closes it.
const T_END = 4 * 3600, BOOST_S = 120, BOOST_RATE = 1 / 3600;

function trial(seed, mode) {
  const sim = new Sim({ seed });
  let T = SET - 1, heat = 0, lastReading = 0, reading = T, dead = false;
  const deadAt = sim.uniform(3600, 3 * 3600);
  let safety = false, boostUntil = -1, ctlWants = 0;
  const log = [];                       // arbiter's decisions (keys mode)
  let deadOnS = 0, maxT = T, maxDead = 0, refused = 0, refusedHealthy = 0, latchFired = 0;

  // keys: one function decides the actuator from who is asking, in a written order
  const decide = (src) => {
    let want, why;
    if (safety) { want = 0; why = 'safety-latch'; }
    else if (sim.now < boostUntil && reading <= SET + CEIL) { want = 1; why = 'boost'; }
    else { want = ctlWants; why = 'ctl'; }
    if (src === 'boost' && safety) { refused++; if (!dead) refusedHealthy++; log.push([sim.now, 'refuse', 'boost', why]); }
    if (want !== heat) log.push([sim.now, want ? 'on' : 'off', src, why]);
    heat = want;
  };
  const set = (src, v) => {             // the only path to the relay
    if (mode === 'lww') { heat = v; return; }
    decide(src);
  };

  sim.process(function* plant() {        // 1 s Euler step, sensor every 1 s
    for (;;) {
      T += (P * heat - UA * (T - AMB)) / C;
      maxT = Math.max(maxT, T);
      if (dead && heat) deadOnS++;
      if (dead) maxDead = Math.max(maxDead, T);
      if (sim.now >= deadAt) dead = true;
      if (!dead) { reading = T; lastReading = sim.now; }
      yield sim.timeout(1);
    }
  });
  sim.process(function* ctl() {          // bang-bang with its own stale fail-safe; writes on change
    yield sim.timeout(0.5);
    let sent = -1;
    for (;;) {
      const stale = sim.now - lastReading > STALE;
      if (stale) { ctlWants = 0; if (mode === 'keys' && !safety) { safety = true; latchFired++; decide('safety'); } }
      else if (reading < SET - H) ctlWants = 1;
      else if (reading > SET + H) ctlWants = 0;
      if (mode === 'keys') decide('ctl');   // the arbiter re-decides every tick, so a ceiling applies mid-boost
      else if (ctlWants !== sent) { set('ctl', ctlWants); sent = ctlWants; }
      yield sim.timeout(1);
    }
  });
  sim.process(function* boost() {        // operator presses "boost" (e.g. after adding food)
    for (;;) {
      yield sim.timeout(sim.exponential(BOOST_RATE));
      boostUntil = sim.now + BOOST_S; set('boost', 1);
      yield sim.timeout(BOOST_S); set('boost', 0);
    }
  });
  sim.run({ until: T_END });
  return { deadOnS, maxT, maxDead, refused, refusedHealthy, latchFired, logLen: log.length };
}

const N = +(process.argv[2] ?? 200), S0 = +(process.argv[3] ?? 1);
for (const mode of ['lww', 'keys']) {
  const r = Array.from({ length: N }, (_, i) => trial(S0 + i, mode));
  const on = r.map(x => x.deadOnS).sort((a, b) => a - b);
  const mx = r.map(x => x.maxT).sort((a, b) => a - b);
  const pct = (a, p) => a[Math.min(a.length - 1, Math.floor(p * a.length))];
  const md = r.map(x => x.maxDead).sort((a, b) => a - b);
  const hit = r.filter(x => x.deadOnS > STALE + 1).length;
  console.log(`${mode.padEnd(4)} trials ${N} | heater on with sensor dead: in ${hit} trials (${(100 * hit / N).toFixed(1)}%), ` +
    `p50 ${pct(on, .5)} s, p95 ${pct(on, .95)} s, max ${on[N - 1]} s | max T p50 ${pct(mx, .5).toFixed(2)} p95 ${pct(mx, .95).toFixed(2)} max ${mx[N - 1].toFixed(2)} C | after sensor death p95 ${pct(md, .95).toFixed(2)} max ${md[N - 1].toFixed(2)} C` +
    (mode === 'keys' ? ` | boosts refused ${r.reduce((s, x) => s + x.refused, 0)} (while sensor healthy: ${r.reduce((s, x) => s + x.refusedHealthy, 0)})` : ''));
}

council/proposals/morphyx-mismatch.mjs:
// Morphyx, council 2 round 2. modulo-bath.mjs's controller and plausibility check, unchanged,
// but the plant's TRUE parameters are split from the MODEL the check believes.
// The check reads P (the assumed plant); the water obeys Q = {...P, ...truth}.
// node morphyx-mismatch.mjs   (~20 s)
import { Sim } from '../tools/des/des.mjs';

// node morphyx-mismatch.mjs [DIV] [MIN]: trip when rise < expect/DIV, if expect >= MIN K (Modulo's: 3, 1.5)
const DIV = +(process.argv[2] ?? 3), MIN = +(process.argv[3] ?? 1.5);
const P = { C: 5 * 4186, UA: 8, W: 1000, amb: 20, dead: 20, noise: 0.05, q: 0.0625 };

function bath({ law, tick = 1.5, seed = 1, hours = 4, set = 60, faultAt = null, faultValue = null, truth = {} }) {
  const Q = { ...P, ...truth };
  const sim = new Sim({ seed });
  let T = Q.amb, heat = 0, peak = -Infinity, tripped = null, tripAt = null;
  const pipe = new Array(Q.dead).fill(0);
  const gauss = () => { let u = 0; for (let i = 0; i < 12; i++) u += sim.random(); return u - 6; };
  sim.process(function* plant() {
    for (;;) {
      pipe.push(heat * Q.W); const q = pipe.shift();
      T += (q - Q.UA * (T - Q.amb)) / Q.C;
      peak = Math.max(peak, T);
      const read = Math.round((T + P.noise * gauss()) / P.q) * P.q;
      sim.inject('temp', faultAt != null && sim.now >= faultAt ? faultValue : read);
      yield sim.timeout(1);
    }
  });
  sim.process(function* ctl() {
    let lastSeen = 0, integ = 0, duty = 0, wStart = -Infinity, y = P.amb;
    const hist = [];
    for (;;) {
      const r = yield sim.anyOf([sim.timeout(tick), sim.signal('temp')]);
      if (r.index === 1) { y = r.value; lastSeen = sim.now; hist.push([sim.now, y, heat]); }
      if (!tripped) {
        const old = hist.filter(([t]) => t >= sim.now - 180 && t <= sim.now - 20);
        const onFrac = old.length ? old.filter(([, , h]) => h).length / old.length : 0;
        if (!Number.isFinite(y) || y < -10 || y > 105) tripped = 'range';
        else if (old.length >= 150) {
          const span = old[old.length - 1][0] - old[0][0] + 1;
          const expect = (P.W * onFrac - P.UA * (old[0][1] - P.amb)) * span / P.C;   // MODEL, not truth
          if (expect >= MIN && y - old[0][1] < expect / DIV) tripped = 'no-rise';
        }
        if (hist.length > 400) hist.splice(0, 200);
      }
      if (tripped && tripAt == null) tripAt = sim.now;
      if (tripped || sim.now - lastSeen > 5 || y > set + 5) { heat = 0; continue; }
      if (law === 'bang') { if (y < set - 0.3) heat = 1; else if (y > set + 0.3) heat = 0; }
      else {
        if (sim.now - wStart >= 10) {
          wStart = sim.now; const e = set - y, Kp = 0.25, Ti = 600;
          const u0 = Kp * e + integ;
          if ((u0 < 1 || e < 0) && (u0 > 0 || e > 0)) integ += Kp * e * 10 / Ti;
          duty = Math.min(1, Math.max(0, Kp * e + integ));
        }
        heat = sim.now - wStart < duty * 10 ? 1 : 0;
      }
    }
  });
  sim.run({ until: hours * 3600 });
  return { peak, tripped, tripAt };
}

const cases = [['as modelled', {}], ['10 L not 5 L', { C: 10 * 4186 }], ['800 W element', { W: 800 }],
  ['lid off, UA x3', { UA: 24 }], ['dead time 60 s', { dead: 60 }], ['room 12 C', { amb: 12 }],
  ['3 L not 5 L', { C: 3 * 4186 }], ['1.5 kW element', { W: 1500 }]];
console.log('model = 5 L, 1 kW, UA 8, dead 20 s, room 20 C; 20 healthy runs (bang+pi, seeds 1-10), 4 h');
for (const [name, truth] of cases) {
  let ft = 0, n = 0; const first = [];
  for (const law of ['bang', 'pi']) for (let seed = 1; seed <= 10; seed++) {
    const r = bath({ law, seed, truth }); n++;
    if (r.tripped) { ft++; if (first.length < 2) first.push(`${law}:${r.tripped}@${(r.tripAt / 60).toFixed(1)}min`); }
  }
  const fz = ['bang', 'pi'].map((law) => {
    const r = bath({ law, faultAt: 10800, faultValue: 59, truth });
    const pre = r.tripAt != null && r.tripAt < 10800;
    return `${law} ${pre ? 'already tripped' : r.tripped ? '+' + (r.tripAt - 10800) + 's' : 'MISSED'} peak ${r.peak.toFixed(1)}`;
  });
  console.log(`${name.padEnd(15)} false trips ${String(ft).padStart(2)}/${n} ${first.join(' ').padEnd(34)}| frozen 59: ${fz.join('; ')}`);
}

