  {
    "name": "local-search fallback off (gives up on a feasible team)",
    "file": "lib/assign.mjs",
    "from": "const sol = anneal(P, ds, wk, avail, B, seed);",
    "to": "const sol = null;"
  },
  {
    "name": "rest-next-to-forced-runs propagation off",
    "file": "lib/assign.mjs",
    "from": "if (a + 1 + b > MAX_RUN) rest.push(d);",
    "to": "if (false) rest.push(d);"
  },
  {
    "name": "rest-next-to-forced-runs one too strong: cuts at MAX_RUN (false refusals)",
    "file": "lib/assign.mjs",
