// node shelf/rota-ref.mjs <dir> team.json START DAYS
// Exact referee for one team: plain DFS over lawful pairs, memo on (day, runs, totals, weekend totals),
// 40M-node budget. Prints FEASIBLE (and checkRota's verdict on what it found), IMPOSSIBLE, or budget.
// Trust "IMPOSSIBLE"; "budget" means nothing. Agreed with makeRota on 120/120 small random teams.
// Uses only <dir>/lib/{policy,calendar}.mjs, never assign.mjs. Modulo, rota 4th.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
const [dir, file, S, N0] = process.argv.slice(2); const N = +N0;
const { bounds, checkRota } = await import(pathToFileURL(resolve(dir, 'lib/policy.mjs')).href);
const { days, isWeekend } = await import(pathToFileURL(resolve(dir, 'lib/calendar.mjs')).href);
const P = JSON.parse(readFileSync(file, 'utf8')).map((p) => ({ ...p, leave: new Set(p.leave) }));
const ds = days(S, N), wk = ds.map(isWeekend), k = P.length;
const B = bounds(P, S, N);
const av = P.map((p) => ds.map((d) => !p.leave.has(d)));
const isN = P.map((p) => p.role === 'nurse');
const pairs = ds.map((_, d) => { const o = []; for (let i = 0; i < k; i++) for (let j = i + 1; j < k; j++) if (av[i][d] && av[j][d] && (isN[i] || isN[j])) o.push([i, j]); return o; });
// suffix availability counts for pruning
const remAv = P.map((_, i) => { const r = new Array(N + 1).fill(0); for (let d = N - 1; d >= 0; d--) r[d] = r[d + 1] + (av[i][d] ? 1 : 0); return r; });
const remWk = P.map((_, i) => { const r = new Array(N + 1).fill(0); for (let d = N - 1; d >= 0; d--) r[d] = r[d + 1] + (av[i][d] && wk[d] ? 1 : 0); return r; });
const fail = new Set(); let nodes = 0; const LIM = 4e7;
const run = new Array(k).fill(0), t = new Array(k).fill(0), w = new Array(k).fill(0), pick = [];
function dfs(d) {
  if (++nodes > LIM) throw new Error('budget');
  if (d === N) return P.every((_, i) => t[i] >= B[i].lo && w[i] >= B[i].wlo);
  for (let i = 0; i < k; i++) if (t[i] + remAv[i][d] < B[i].lo || w[i] + remWk[i][d] < B[i].wlo) return false;
  const key = d + '|' + run.join(',') + '|' + t.join(',') + '|' + w.join(',');
  if (fail.has(key)) return false;
  for (const [a, b] of pairs[d]) {
    if (run[a] >= 5 || run[b] >= 5 || t[a] >= B[a].hi || t[b] >= B[b].hi) continue;
    if (wk[d] && (w[a] >= B[a].whi || w[b] >= B[b].whi)) continue;
    const saved = run.slice();
    for (let x = 0; x < k; x++) run[x] = (x === a || x === b) ? run[x] + 1 : 0;
    t[a]++; t[b]++; if (wk[d]) { w[a]++; w[b]++; } pick.push([a, b]);
    if (dfs(d + 1)) return true;
    pick.pop(); t[a]--; t[b]--; if (wk[d]) { w[a]--; w[b]--; } for (let x = 0; x < k; x++) run[x] = saved[x];
  }
  fail.add(key); return false;
}
const t0 = Date.now();
try {
  const ok = dfs(0);
  console.log('exact:', ok ? 'FEASIBLE' : 'IMPOSSIBLE', nodes, 'nodes', Date.now() - t0, 'ms');
  if (ok) { const r = Object.fromEntries(ds.map((d, i) => [d, pick[i].map((x) => P[x].name)])); console.log('checkRota breaches', checkRota(P, S, N, r).length); }
} catch (e) { console.log('exact:', e.message, nodes, Date.now() - t0, 'ms'); }

shelf/rota-stress.mjs:
#!/usr/bin/env node
// rota-stress.mjs — judge a rota program against POLICY.md on random teams, and measure drift.
//   node shelf/rota-stress.mjs <dir> stress SEED COUNT     random teams: made / refused (by reason) / gave up / UNLAWFUL, worst ms
//   node shelf/rota-stress.mjs <dir> drift PERIODS          clinic people.json, no leave, consecutive 28-day periods:
//                                                           cumulative (shifts − share) per person, totals and weekends
//   node shelf/rota-stress.mjs <dir> clinic START DAYS      people.json: breaches + share vs got, per person
// <dir> holds lib/assign.mjs (makeRota), lib/policy.mjs (checkRota, shares), lib/people.mjs.
// Made by Morphyx (rota, third time). Re-derived three times by hand before it was shelved.
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
const [dir = '.', mode = 'stress', a, b] = process.argv.slice(2);
const lib = (f) => import(pathToFileURL(resolve(dir, 'lib', f)).href);
const { makeRota } = await lib('assign.mjs');
const { checkRota, shares, tally } = await lib('policy.mjs');
const { loadPeople } = await lib('people.mjs');

function mulberry32(s) { return () => { s |= 0; s = (s + 0x6d2b79f5) | 0; let t = Math.imul(s ^ (s >>> 15), 1 | s); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
const addDays = (s, k) => new Date(Date.parse(`${s}T00:00:00Z`) + k * 864e5).toISOString().slice(0, 10);

export function randomTeam(rnd) {
  const n = rnd() < 0.2 ? 60 + Math.floor(rnd() * 306) : 7 + Math.floor(rnd() * 50);
  const start = addDays('2026-01-01', Math.floor(rnd() * 365));
  const k = 3 + Math.floor(rnd() * 10);
  const people = Array.from({ length: k }, (_, i) => {
    const leave = new Set();
    for (let j = Math.floor(rnd() * 4); j > 0; j--) { const s = Math.floor(rnd() * n), L = 1 + Math.floor(rnd() * 10); for (let x = 0; x < L; x++) leave.add(addDays(start, s + x)); }
    return { name: `P${i}`, role: i === 0 || rnd() < 0.5 ? 'nurse' : 'aide', fte: rnd() < 0.6 ? 1 : Math.round((0.2 + rnd() * 0.8) * 10) / 10, leave };
  });
  return { people, start, n };
}

if (mode === 'stress') {
  const rnd = mulberry32(Number(a ?? 1)), count = Number(b ?? 200);
  const res = { made: 0, unlawful: 0, gaveUp: 0, refused: {} }; let worst = 0, worstCase = '';
  for (let c = 0; c < count; c++) {
    const { people, start, n } = randomTeam(rnd);
    const t0 = performance.now();
    try {
      const r = makeRota(people, start, n);
      const bad = checkRota(people, start, n, r);
      if (bad.length) { res.unlawful++; console.log('UNLAWFUL', start, n, bad.slice(0, 3)); } else res.made++;
    } catch (e) {
      if (/search steps/.test(e.message)) { res.gaveUp++; console.log('GAVE UP', start, n, JSON.stringify(people.map((p) => ({ ...p, leave: [...p.leave].sort() })))); }
      else {
        if (/exhaustive/.test(e.message) || process.env.SHOW_REFUSED) console.log('REFUSED', start, n, JSON.stringify(people.map((p) => ({ ...p, leave: [...p.leave].sort() }))), '\n ', e.message);
        const key = e.message.replace(/\d{4}-\d{2}-\d{2}/g, 'D').replace(/\d+/g, 'N'); res.refused[key] = (res.refused[key] || 0) + 1; }
    }
    const ms = performance.now() - t0; if (ms > worst) { worst = ms; worstCase = `${start} ${n}d ${people.length}p`; }
  }
  console.log(JSON.stringify(res, null, 1)); console.log(`worst ${worst.toFixed(0)} ms (${worstCase})`);
} else if (mode === 'drift') {
  const P = Number(a ?? 26);
  const people = loadPeople(resolve(dir, 'people.json')).map((p) => ({ ...p, leave: new Set() }));
  const acc = Object.fromEntries(people.map((p) => [p.name, { t: 0, w: 0 }]));
  for (let q = 0; q < P; q++) {
    const start = addDays('2026-11-02', 28 * q), r = makeRota(people, start, 28), t = tally(people, r);
    if (checkRota(people, start, 28, r).length) console.log('UNLAWFUL period', q);
    for (const s of shares(people, start, 28)) { acc[s.name].t += t[s.name].total - s.total; acc[s.name].w += t[s.name].weekend - s.weekend; }
  }
  for (const [k, v] of Object.entries(acc)) console.log(k.padEnd(8), 'total', v.t.toFixed(2).padStart(7), ' weekend', v.w.toFixed(2).padStart(7));
} else if (mode === 'clinic') {
  const people = loadPeople(resolve(dir, 'people.json')), start = a ?? '2026-11-02', n = Number(b ?? 28);
  const r = makeRota(people, start, n), t = tally(people, r);
  console.log('breaches:', checkRota(people, start, n, r));
  for (const s of shares(people, start, n)) console.log(s.name.padEnd(8), 'share', s.total.toFixed(2), 'got', t[s.name].total, ' wk share', s.weekend.toFixed(2), 'got', t[s.name].weekend);
}

shelf/rota-why.mjs:
// rota-why.mjs — node shelf/rota-why.mjs <dir> SEED:COUNT [SEED:COUNT ...]
// Pulls every exhaustive (unnamed) refusal and give-up out of rota-stress for those seeds, prints each
// team as a day grid (x work day, w weekend, . leave) with its bounds, and asks an independent memoized
// referee whether a rota exists with each rule switched off. The rules whose removal makes it feasible
// are the cause. "budget" = the referee gave up (3M nodes). Modulo, rota 4th.
import { spawnSync } from 'node:child_process';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
const dir = resolve(process.argv[2] ?? '.');
const here = dirname(fileURLToPath(import.meta.url));
const { days, isWeekend } = await import(`${dir}/lib/calendar.mjs`);
const { bounds } = await import(`${dir}/lib/policy.mjs`);
const { validatePeople } = await import(`${dir}/lib/people.mjs`);
const specs = process.argv.slice(3).map((x) => x.split(':').map(Number));
if (!specs.length) { console.error('usage: node shelf/rota-why.mjs <dir> SEED:COUNT [...]'); process.exit(2); }

const teams = [];
for (const [s, c] of specs) {
  const out = spawnSync(process.execPath, [`${here}/rota-stress.mjs`, dir, 'stress', s, c], { encoding: 'utf8' }).stdout.split('\n');
  out.forEach((l, i) => {
    const m = l.match(/^(REFUSED|GAVE UP) (\S+) (\d+) (.*)$/);
    if (m && (m[1] === 'GAVE UP' || /exhaustive/.test(out[i + 1] ?? ''))) teams.push({ seed: s, kind: m[1], start: m[2], n: +m[3], people: validatePeople(JSON.parse(m[4])) });
  });
}
if (!teams.length) console.log('no exhaustive refusals or give-ups for these seeds');
{
}

// Referee: does a rota exist with the given rules on? off = set of 'r3','r4lo','r4hi','r5lo','r5hi','nurse'
function exists(P, start, n, off = new Set()) {
  const ds = days(start, n), wk = ds.map(isWeekend), B = bounds(P, start, n), k = P.length;
  const lo = B.map((b) => (off.has('r4lo') ? 0 : b.lo)), hi = B.map((b) => (off.has('r4hi') ? 1e9 : b.hi));
  const wlo = B.map((b) => (off.has('r5lo') ? 0 : b.wlo)), whi = B.map((b) => (off.has('r5hi') ? 1e9 : b.whi));
  const MR = off.has('r3') ? 1e9 : 5;
  const run = new Array(k).fill(0), tot = new Array(k).fill(0), wkc = new Array(k).fill(0);
  const failed = new Set();
  let nodes = 0;
  function go(d) {
    if (++nodes > 3e6) throw new Error('budget');
    if (d === n) return tot.every((t, i) => t >= lo[i]) && wkc.every((t, i) => t >= wlo[i]);
    for (let i = 0; i < k; i++) { const left = n - d; if (tot[i] + left < lo[i]) return false; }
    const key = `${d}|${run}|${tot}|${wkc}`;
    if (failed.has(key)) return false;
    const ok = (i) => !P[i].leave.has(ds[d]) && run[i] < MR && tot[i] < hi[i] && !(wk[d] && wkc[i] >= whi[i]);
    for (let i = 0; i < k; i++) if (ok(i)) for (let j = i + 1; j < k; j++) if (ok(j)) {
      if (!off.has('nurse') && P[i].role !== 'nurse' && P[j].role !== 'nurse') continue;
      const sr = run.slice();
      for (let x = 0; x < k; x++) run[x] = x === i || x === j ? sr[x] + 1 : 0;
      tot[i]++; tot[j]++; if (wk[d]) { wkc[i]++; wkc[j]++; }
      const r = go(d + 1);
      tot[i]--; tot[j]--; if (wk[d]) { wkc[i]--; wkc[j]--; }
      for (let x = 0; x < k; x++) run[x] = sr[x];
      if (r) return true;
    }
    failed.add(key);
    return false;
  }
  return go(0);
}

for (const t of teams) {
  const ds = days(t.start, t.n);
  console.log(`\n== ${t.kind} seed ${t.seed} ${t.start} ${t.n}d ${t.people.length}p`);
  const B = bounds(t.people, t.start, t.n);
  for (const [i, p] of t.people.entries()) console.log(`${p.name.padEnd(4)} ${p.role.padEnd(5)} ${p.fte} ${ds.map((d) => (p.leave.has(d) ? '.' : isWeekend(d) ? 'w' : 'x')).join('')}  tot ${B[i].total.toFixed(2)} [${B[i].lo},${B[i].hi}] wk ${B[i].weekend.toFixed(2)} [${B[i].wlo},${B[i].whi}]`);
  for (const off of [[], ['r3'], ['r4lo'], ['r4hi'], ['r5lo'], ['r5hi'], ['nurse']]) {
    let r; try { r = exists(t.people, t.start, t.n, new Set(off)); } catch { r = 'budget'; }
    console.log(`  off ${off.join(',') || '(none)'}: ${r}`);
  }
}

shelf/stopwatch-ceiling.mjs:
// node shelf/stopwatch-ceiling.mjs [N] — how many patients could ANY controller time on the stand-in
// clinic, if it knew every wait in advance? Earliest-finish-first is optimal for interval
// scheduling, so it is the ceiling; greedy-by-arrival is what stopwatch.mjs does. If the
// two are close, no cleverer whom-to-time rule can buy the lumpy cell its patients. — Morphyx
import { makeClinic } from '../clinic-sim.mjs';
const N = +process.argv[2] || 400;
const loads = [[1 / 12, 1, 'queue'], [1 / 40, 1, 'queue'], [1 / 5, 2, 'queue'], [7.53 / 420, 1, 'tri']];
for (const [rate, servers, waits] of loads) {
  let g = 0, o = 0, arrivals = 0;
  for (let s = 1; s <= N; s++) {
    const c = makeClinic({ seed: s, rate, servers, waits });
    for (const [, day] of c.secret.days) {
      const iv = day.patients.map((p) => [p.arrive, p.arrive + day.truth.get(p.id).stop]);
      arrivals += iv.length;
      let free = -Infinity; for (const [a, e] of iv) if (a >= free) { g++; free = e; }
      free = -Infinity; for (const [a, e] of [...iv].sort((x, y) => x[1] - y[1])) if (a >= free) { o++; free = e; }
    }
  }
  console.log(`1/${Math.round(1 / rate)} x${servers} ${waits}`.padEnd(18), `arrivals ${(arrivals / N).toFixed(1)}  greedy ${(g / N).toFixed(1)}  oracle ${(o / N).toFixed(1)}  (per 5 mornings)`);
}

shelf/stopwatch-lean.mjs:
// node shelf/stopwatch-lean.mjs [N] — do greedy's timed patients wait less than patients in
// general? Busy stretches keep the observer busy, so their patients are skipped more. The
// study is unbiased only because SPEC promises differences don't depend on waits; this
// shows how much that promise is carrying. — Morphyx
import { makeClinic } from '../clinic-sim.mjs';
const N = +process.argv[2] || 400;
for (const [rate, servers, waits] of [[1 / 12, 1, 'queue'], [1 / 40, 1, 'queue'], [1 / 5, 2, 'queue'], [7.53 / 420, 1, 'tri']]) {
  let all = 0, na = 0, tw = 0, nt = 0;
  for (let s = 1; s <= N; s++) {
    for (const [, day] of makeClinic({ seed: s, rate, servers, waits }).secret.days) {
      let free = -Infinity;
      for (const p of day.patients) {
        const w = day.truth.get(p.id).stop; all += w; na++;
        if (p.arrive >= free) { tw += w; nt++; free = p.arrive + w; }
      }
    }
  }
  console.log(`1/${Math.round(1 / rate)} x${servers} ${waits}`.padEnd(18), `mean wait all ${(all / na).toFixed(1)}  timed ${(tw / nt).toFixed(1)} min`);
}

shelf/vv-spec-check.mjs:
#!/usr/bin/env node
// node shelf/vv-spec-check.mjs [dir-with-vv.mjs=.] [seed=1] [count=400]
// An independent reading of vv SPEC.md (written without opening vv.mjs), plus
// hand-worked black-box checks and a differential fuzzer against <dir>/vv.mjs.
// TPM and EVM are worked in exact rational arithmetic (BigInt), so a float
// answer that lands on the wrong side of a boundary shows up as a disagreement.
// Exit 1 on any failure. — Morphyx
import { pathToFileURL } from 'node:url';
import { resolve, join } from 'node:path';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { execFileSync } from 'node:child_process';

// ---------- exact rationals ----------
const bgcd = (a, b) => { a = a < 0n ? -a : a; b = b < 0n ? -b : b; while (b) [a, b] = [b, a % b]; return a; };
class Q {
  constructor(n, d = 1n) { if (d < 0n) { n = -n; d = -d; } const g = bgcd(n, d) || 1n; this.n = n / g; this.d = d / g; }
  static of(x) {
    if (x instanceof Q) return x;
    if (Number.isInteger(x)) return new Q(BigInt(x));
    const [s, e = '0'] = String(x).split(/e/i), ex = BigInt(e);
    const [i, f = ''] = s.split('.'); const q = new Q(BigInt(i + f), 10n ** BigInt(f.length));
    return ex >= 0n ? q.mul(new Q(10n ** ex)) : q.div(new Q(10n ** -ex));
  }
  add(o) { o = Q.of(o); return new Q(this.n * o.d + o.n * this.d, this.d * o.d); }
  sub(o) { o = Q.of(o); return new Q(this.n * o.d - o.n * this.d, this.d * o.d); }
  mul(o) { o = Q.of(o); return new Q(this.n * o.n, this.d * o.d); }
  div(o) { o = Q.of(o); return new Q(this.n * o.d, this.d * o.n); }
  cmp(o) { o = Q.of(o); const l = this.n * o.d, r = o.n * this.d; return l < r ? -1 : l > r ? 1 : 0; }
  isZero() { return this.n === 0n; }
  floor() { let q = this.n / this.d; if (this.n % this.d !== 0n && this.n < 0n) q -= 1n; return q; }
  num() { return Number(this.n) / Number(this.d); }
}
const Z = new Q(0n);

// ---------- the reading ----------
const ID = /^[A-Z][A-Z0-9]*(-[A-Z0-9]+)*$/;
const STR = ['shall', 'should', 'may'], MET = ['test', 'analysis', 'inspection', 'demonstration'];
const sortS = a => [...a].sort();
const day = s => Date.UTC(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10)) / 86400000;
const iso = n => new Date(n * 86400000).toISOString().slice(0, 10);
const hasParent = r => r.parent !== null && r.parent !== undefined;

function leafSet(list) {
  const named = new Map(); // parent id -> set of indices naming it
  list.forEach((r, i) => { if (hasParent(r)) { if (!named.has(r.parent)) named.set(r.parent, new Set()); named.get(r.parent).add(i); } });
  // leaf: no OTHER requirement names it as parent (self-parent alone stays a leaf)
  return list.map((r, i) => { const s = named.get(r.id); return !s || [...s].every(j => j === i); });
}

export function load(list) {
  const probs = [], ids = new Set(list.map(r => r.id)), seen = new Set(), dup = new Set();
  const leaf = leafSet(list);
  const par = new Map(); for (const r of list) if (!par.has(r.id)) par.set(r.id, hasParent(r) ? r.parent : null);
  list.forEach((r, i) => {
    if (typeof r.id !== 'string' || !ID.test(r.id)) probs.push({ id: r.id, code: 'bad-id' });
    if (seen.has(r.id)) { if (!dup.has(r.id)) { dup.add(r.id); probs.push({ id: r.id, code: 'duplicate-id' }); } } else seen.add(r.id);
    if (hasParent(r) && !ids.has(r.parent)) probs.push({ id: r.id, code: 'unknown-parent' });
    if (leaf[i] && !MET.includes(r.method)) probs.push({ id: r.id, code: 'bad-method' });
    if (leaf[i] && r.strength === 'shall' && !(typeof r.acceptance === 'string' && r.acceptance.trim() !== '')) probs.push({ id: r.id, code: 'missing-acceptance' });
  });
  const onCycle = new Set();
  for (const start of par.keys()) { // walk up; a node is on a cycle iff walking returns to it
    let x = par.get(start), steps = 0;
    while (x !== null && x !== undefined && par.has(x) && steps <= par.size) { if (x === start) { onCycle.add(start); break; } x = par.get(x); steps++; }
  }
  const cyc = new Set(); list.forEach(r => { if (onCycle.has(r.id) && !cyc.has(r.id)) { cyc.add(r.id); probs.push({ id: r.id, code: 'cycle' }); } });
  { const k = new Set(); for (let i = probs.length - 1; i >= 0; i--) { const key = probs[i].id + '\u0000' + probs[i].code; if (k.has(key)) probs.splice(i, 1); else k.add(key); } } // one {id,code} pair per id (decision: same as vv)
  probs.sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : a.code < b.code ? -1 : a.code > b.code ? 1 : 0));
  return { reqs: list, problems: probs };
}

const VAGUE = ['fast', 'quickly', 'user-friendly', 'easy', 'robust', 'efficient', 'flexible', 'adequate', 'appropriate', 'as needed', 'state-of-the-art', 'etc'];
