    const den = sxx.mul(new Q(n)).sub(sx.mul(sx));
    if (!den.isZero()) { b = sxy.mul(new Q(n)).sub(sx.mul(sy)).div(den); a = sy.sub(b.mul(sx)).div(new Q(n)); trend = b.num(); }
  }
